<?php
namespace App\Interfaces\Http\Controllers\Api\V1\Customers;use App\Application\Privacy\ConsentService;use App\Models\Consent;use App\Models\Party;use App\Models\Tenant;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;
final class ConsentController{public function store(Request$r,ConsentService$s):JsonResponse{$d=$r->validate(['party_id'=>'required|uuid|exists:parties,id','tenant_id'=>'nullable|uuid|exists:tenants,id','purpose'=>'required|in:INSURANCE_SERVICES,MARKETING,DATA_SHARING,CLAIMS_PROCESSING','notice_version'=>'required|string|max:32','channel'=>'required|in:WEB,ASSISTED,PAPER,API','affirmed'=>'required|accepted','evidence_reference'=>'required|string|max:255']);$party=Party::findOrFail($d['party_id']);$tenantId=app(\App\Domain\Tenancy\TenantContext::class)->id();$system=$r->user()->memberships()->where('role_code','SYSTEM_ADMIN')->where('status','ACTIVE')->exists();abort_unless($party->customers()->where('tenant_id',$tenantId)->exists()||$system,404);abort_unless(!isset($d['tenant_id'])||$d['tenant_id']===$tenantId||$system,403);$c=$s->grant($party,isset($d['tenant_id'])?Tenant::findOrFail($d['tenant_id']):null,$d['purpose'],$d['notice_version'],$d['channel'],['affirmed'=>true,'reference'=>$d['evidence_reference']],$r->user());return response()->json(['data'=>$c],201);}public function withdraw(Request$r,Consent$consent,ConsentService$s):JsonResponse{abort_unless($consent->tenant_id===app(\App\Domain\Tenancy\TenantContext::class)->id()||$r->user()->memberships()->where('role_code','SYSTEM_ADMIN')->where('status','ACTIVE')->exists(),404);$d=$r->validate(['reason'=>'required|string|max:64','notes'=>'required|string|min:10|max:1000']);return response()->json(['data'=>$s->withdraw($consent,$d['reason'],['notes'=>$d['notes']],$r->user())]);}}
